// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(0));
        airPort helper = new airPort();
        vm.assume(caddress != address(helper));
        CallCounter counter = new CallCounter();
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(_tos[i] != address(c));
            vm.assume(_tos[i] != address(helper));
            vm.assume(_tos[i] != address(counter));
        }
        bool success;
        try c.transfer(from, address(counter), _tos, v) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }
        assertTrue(success && counter.count() == _tos.length);
    }
}

contract CallCounter {
    uint256 public count;
    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        return true;
    }
}
